using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;

[McpServerToolType]
public static class WeatherTools
{
    [McpServerTool, Description("Get current weather for a location by latitude and longitude.")]
    public static async Task<string> GetCurrentWeather(
        IHttpClientFactory httpClientFactory,
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        var client = httpClientFactory.CreateClient("WeatherApi");

        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&current=temperature_2m,wind_speed_10m";

        using var response = await client.GetAsync(url);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>();
        var current = json.GetProperty("current");

        var temp = current.GetProperty("temperature_2m").GetDouble();
        var wind = current.GetProperty("wind_speed_10m").GetDouble();

        return $"Temperature: {temp}°C, Wind: {wind} km/h";
    }

    [McpServerTool, Description("Look up coordinates for a city name.")]
    public static async Task<string> GeocodeCity(
        IHttpClientFactory httpClientFactory,
        [Description("City name to look up")] string city)
    {
        var client = httpClientFactory.CreateClient("WeatherApi");

        var url = $"v1/forecast?latitude=0&longitude=0&current=temperature_2m"
                + $"&geocoding=true";
        // Open-Meteo geocoding is a separate endpoint:
        var geocodeClient = new HttpClient { BaseAddress = new Uri("https://geocoding-api.open-meteo.com/") };
        var geoUrl = $"v1/search?name={Uri.EscapeDataString(city)}&count=1";

        using var response = await geocodeClient.GetAsync(geoUrl);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>();

        if (!json.TryGetProperty("results", out var results) || results.GetArrayLength() == 0)
            return $"No results found for '{city}'.";

        var first = results[0];
        var lat = first.GetProperty("latitude").GetDouble();
        var lon = first.GetProperty("longitude").GetDouble();
        var name = first.GetProperty("name").GetString();

        return $"{name}: latitude={lat}, longitude={lon}";
    }
}

